from __future__ import annotations

import asyncio
import hashlib
import json
import os
import random
import threading
import time
from copy import deepcopy
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from park_twin_engine import apply_stress_event, noisy_observation, score_outcome, simulate_action_plan, transition_state
from park_replay_store import append_replay_event, create_replay_run, list_replay_events, list_replay_runs


BASE_DIR = Path(__file__).resolve().parent
RUNTIME_RNG = random.SystemRandom()


class AsyncThreadLock:
    def __init__(self) -> None:
        self._lock = threading.Lock()

    async def __aenter__(self):
        while not self._lock.acquire(blocking=False):
            await asyncio.sleep(0.001)
        return self

    async def __aexit__(self, exc_type, exc, tb) -> None:
        self._lock.release()


def _utc_now() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z")


def _env_float(name: str, default: float) -> float:
    try:
        return float(os.getenv(name, str(default)))
    except ValueError:
        return default


class ParkSimulation:
    def __init__(self) -> None:
        self.lock = AsyncThreadLock()
        self.minute = 45
        self.hour = 11
        self.scenario_key = "ride_down"
        self.active_policy = "normal"
        self.last_actions: list[dict[str, Any]] = []
        self.interventions: list[dict[str, Any]] = []
        self.dynamic_state: dict[str, Any] | None = None
        self.replay_events: list[dict[str, Any]] = []
        self.replay_seed = "demo"
        self.replay_run = create_replay_run(self.replay_seed, self.scenario_key)
        self.replay_run_id = str(self.replay_run["run_id"])
        self.tick_index = 0
        self.last_random_incident_tick = -999
        self.episode_fitness: list[dict[str, Any]] = []

    async def step(self) -> None:
        async with self.lock:
            self.tick_index += 1
            self.minute += 1
            if self.minute >= 60:
                self.minute = 0
                self.hour = (self.hour + 1) % 24
            previous_dynamic_state = self.dynamic_state
            self.dynamic_state = None
            base_state = self._state(include_industrial=False)
            self.dynamic_state = previous_dynamic_state
            self.dynamic_state = transition_state(
                base_state,
                {"target": "none", "action": "natural"},
                minutes=1,
                seed=f"runtime:{time.time_ns()}:{RUNTIME_RNG.random()}",
                stochastic=True,
            )
            self._maybe_inject_random_unexpected_event_locked("live_tick")
            self.interventions = _drop_expired_runtime_interventions(self.interventions, self.tick_index)

    async def get_state(self) -> dict[str, Any]:
        async with self.lock:
            return self._state()

    async def get_state_lite(self) -> dict[str, Any]:
        async with self.lock:
            return self._state(include_industrial=False)

    async def set_time(self, hour: int, minute: int = 0) -> dict[str, Any]:
        async with self.lock:
            self.hour = max(0, min(23, int(hour)))
            self.minute = max(0, min(59, int(minute)))
            self.dynamic_state = None
            return self._state(include_industrial=False)

    async def get_replay(self, limit: int = 20) -> dict[str, Any]:
        async with self.lock:
            safe_limit = max(1, min(100, int(limit or 20)))
            events = list_replay_events(self.replay_run_id, safe_limit) or deepcopy(self.replay_events[:safe_limit])
            return {
                "mode": "sqlite_persistent_simulation_replay",
                "run": deepcopy(self.replay_run),
                "run_id": self.replay_run_id,
                "seed": self.replay_seed,
                "event_count": len(events),
                "events": events,
                "latest_event": events[0] if events else None,
                "recent_runs": list_replay_runs(8),
            }

    async def get_episode_fitness(self, limit: int = 20) -> dict[str, Any]:
        async with self.lock:
            return self._episode_fitness_payload_locked(limit)

    async def start_replay_run(self, seed: str | None = None, scenario_key: str = "ride_down") -> dict[str, Any]:
        async with self.lock:
            selected_scenario = scenario_key if scenario_key in {"ride_down", "staff_shortage", "food_spike", "storm_response"} else "ride_down"
            selected_seed = (seed or "demo").strip() or "demo"
            self.replay_seed = selected_seed
            self.replay_run = create_replay_run(selected_seed, selected_scenario)
            self.replay_run_id = str(self.replay_run["run_id"])
            self.hour, self.minute = _seeded_time(selected_seed)
            self.scenario_key = selected_scenario
            self.active_policy = "normal"
            self.interventions = []
            self.last_actions = []
            self.replay_events = []
            self.dynamic_state = None
            self.tick_index = 0
            self.last_random_incident_tick = -999
            self.episode_fitness = []
            state = self._state(include_industrial=False)
            self._record_replay_event(
                "run_started",
                f"Seeded replay started for {selected_scenario}",
                state,
                state,
                {"seed": selected_seed, "scenario_key": selected_scenario, "run_id": self.replay_run_id, "status": "success"},
                self.replay_run["created_at"],
            )
            return {
                "status": "success",
                "message": f"Seeded replay {self.replay_run_id} started.",
                "run": deepcopy(self.replay_run),
                "replay": {
                    "mode": "sqlite_persistent_simulation_replay",
                    "run_id": self.replay_run_id,
                    "seed": self.replay_seed,
                    "event_count": 1,
                    "events": deepcopy(self.replay_events),
                    "latest_event": deepcopy(self.replay_events[0]) if self.replay_events else None,
                },
            }

    async def execute_action(self, target: str, action: str) -> dict[str, Any]:
        async with self.lock:
            before = self._state(include_industrial=False)
            created_at = _utc_now()
            requested_target = target
            requested_action = action
            action_aliases = {
                ("ride", "reroute_down_ride"): ("ride", "reroute"),
                ("food", "redirect_food_demand"): ("traffic", "redirect_food"),
                ("staff", "redeploy_staff"): ("staff", "redeploy"),
                ("staff", "redeploy_food_staff"): ("staff", "redeploy_food_certified"),
                ("crowd_safety", "calm_reroute"): ("ride", "reroute"),
                ("guest_care", "family_care_reroute"): ("ride", "reroute"),
                ("equipment", "hold_equipment_changes"): ("energy", "protect_hvac"),
                ("traffic", "capacity_staged_reroute"): ("traffic", "staged_reroute"),
                ("ride", "hold_queue_intake"): ("queue_gate", "hold_intake"),
            }
            target, action = action_aliases.get((target, action), (target, action))
            accepted = {
                ("traffic", "redirect_food"): "Guest app routing shifted demand toward Food Court B and Arcade Zone.",
                ("ride", "reroute"): "Dragon Coaster queue intake paused; guests are split across Sky Drop, Theater B, Arcade Zone, and Food Court B.",
                ("staff", "redeploy"): "Two crowd-control staff moved to Coaster Plaza while protected ride-operator breaks remain intact.",
                ("staff", "redeploy_food_certified"): "Food-certified staff moved to Food Court A pickup and prep bottlenecks while protected breaks remain intact.",
                ("food", "suppress_item"): "Chicken tenders suppressed in mobile order at Food Court A; pizza combo promoted at Food Court B.",
                ("food", "pause_mobile_order_intake"): "New mobile-order intake paused at Food Court A while the pickup backlog is recovered.",
                ("food", "open_temp_pickup"): "Temporary Food Court A pickup lane opened with food-certified staff support.",
                ("food", "open_satellite_cart"): "Satellite food cart opened outside the pressure zone to add service capacity and absorb simple orders.",
                ("food", "throttle_mobile_pickup_windows"): "Mobile pickup windows paced to smooth demand while existing paid orders continue.",
                ("traffic", "staged_reroute"): "Guest app nudges staged guests through multiple lower-pressure destinations with capacity-aware shares.",
                ("energy", "protect_hvac"): "HVAC reduction blocked in indoor shelter zones while guest density remains high.",
                ("medical", "dispatch"): "Medical team dispatched to the reported zone; guest privacy is protected and crowd flow is softened nearby.",
                ("accessibility", "assist"): "Accessibility support dispatched and nearby routing adjusted for mobility needs.",
                ("security", "respond"): "Security and crowd-control leads moved to the incident zone while emergency routes remain clear.",
                ("guest_services", "message"): "Guest Services sent targeted, calm guidance to affected guests without exposing sensitive details.",
                ("signage", "update"): "Digital signage updated to guide guests toward safer, lower-pressure routes.",
                ("queue_gate", "hold_intake"): "Queue intake paused and overflow routing activated for the affected attraction.",
                ("entertainment", "activate"): "A pop-up entertainment pull was activated to draw guests away from the pressure zone.",
                ("maintenance", "inspect"): "Maintenance inspection started; ride reopening remains blocked until clearance is logged.",
            }
            if target == "scenario" and action in {"ride_down", "staff_shortage", "food_spike", "storm_response"}:
                self.scenario_key = action
                self.active_policy = "normal"
                self.interventions = []
                self.dynamic_state = None
                result = {"status": "success", "message": f"ParkPulse scenario switched to {action}."}
                self._record_replay_event(
                    "scenario_switch",
                    f"Scenario switched to {action}",
                    before,
                    self._state(include_industrial=False),
                    {"target": target, "action": action, "status": result["status"]},
                    created_at,
                )
                return result

            message = accepted.get((target, action))
            if not message:
                result = {"status": "noop", "message": f"No ParkPulse action registered for {requested_target}/{requested_action}."}
                self._record_replay_event(
                    "operator_action_noop",
                    f"No registered action for {requested_target}/{requested_action}",
                    before,
                    self._state(include_industrial=False),
                    {"target": requested_target, "action": requested_action, "status": result["status"]},
                    created_at,
                )
                return result

            self.active_policy = action
            projected = transition_state(
                before,
                {"target": target, "action": action, "label": message},
                minutes=8,
                seed=f"{self.replay_seed}:{target}:{action}:{len(self.last_actions)}",
                stochastic=True,
            )
            projected.setdefault("digitalTwin", {})["lastAppliedAction"] = {
                "target": target,
                "action": action,
                "message": message,
                "appliedHorizonMinutes": 8,
                "outcomeScore": score_outcome(before, projected, {"target": target, "action": action})["overall"],
            }
            self.dynamic_state = projected
            fitness_episode = self._record_episode_fitness_locked(
                before=before,
                after=projected,
                action_plan={"target": target, "action": action, "label": message},
                source="operator_action",
                created_at=created_at,
                horizon_minutes=8,
                requested_action={"target": requested_target, "action": requested_action},
            )
            self.last_actions.insert(
                0,
                {
                    "target": target,
                    "action": action,
                    "message": message,
                    "createdAt": created_at,
                },
            )
            self.last_actions = self.last_actions[:8]
            result = {"status": "success", "message": message, "episode_fitness": fitness_episode}
            self._record_replay_event(
                "operator_action",
                f"{target}/{action}",
                before,
                self._state(include_industrial=False),
                {
                    "target": target,
                    "action": action,
                    "requestedTarget": requested_target,
                    "requestedAction": requested_action,
                    "status": result["status"],
                    "message": message,
                },
                created_at,
            )
            return result

    async def apply_delivery_outcomes(self, dispatches: list[dict[str, Any]], reason: str = "closed_loop_outcome") -> dict[str, Any]:
        async with self.lock:
            before = self._state(include_industrial=False)
            created_at = _utc_now()
            def has_observed_response(item: dict[str, Any]) -> bool:
                response = item.get("response", {}) if isinstance(item.get("response"), dict) else {}
                return bool(
                    response.get("state") in {"observed", "acknowledged"} or
                    response.get("takeRate") is not None or
                    response.get("reactiveFollowThroughRate") is not None or
                    response.get("acknowledgedCount") or
                    response.get("followThroughCount") or
                    response.get("applied")
                )

            observed = [item for item in dispatches if isinstance(item, dict) and has_observed_response(item)]
            channels = sorted({str(item.get("channel")) for item in observed if item.get("channel")})
            if not observed:
                result = {"status": "noop", "message": "No observed dispatch response available to apply."}
                self._record_replay_event(
                    "outcome_noop",
                    "No observed dispatch response",
                    before,
                    self._state(include_industrial=False),
                    {"reason": reason, "dispatch_count": len(dispatches), "status": result["status"]},
                    created_at,
                )
                return result

            self.active_policy = "proactive_commit"
            projected = transition_state(
                before,
                {"target": "traffic", "action": "reroute", "label": reason},
                minutes=10,
                seed=f"{self.replay_seed}:{reason}:{len(self.last_actions)}",
                stochastic=True,
            )
            self.dynamic_state = projected
            moved_guests = sum(
                int(item.get("response", {}).get("followThroughCount", 0) or 0)
                for item in observed
                if item.get("channel") == "guest_app"
            )
            worker_acks = sum(
                int(item.get("response", {}).get("acknowledgedCount", 0) or 0)
                for item in observed
                if item.get("channel") == "worker_device"
            )
            equipment_applied = sum(
                1
                for item in observed
                if item.get("channel") == "equipment_controller" and item.get("response", {}).get("applied")
            )

            def zone_by_id(state: dict[str, Any], zone_id: str) -> dict[str, Any] | None:
                zones = state.get("guestFlow", {}).get("zones", [])
                return next((zone for zone in zones if zone.get("id") == zone_id), None)

            def food_location(state: dict[str, Any], target: str) -> dict[str, Any] | None:
                locations = state.get("foodInventory", {}).get("locations", [])
                compact_target = str(target).lower().replace("_", "").replace(" ", "")
                for location in locations:
                    compact_id = str(location.get("id", "")).lower().replace("_", "").replace(" ", "")
                    compact_name = str(location.get("name", "")).lower().replace("_", "").replace(" ", "")
                    if compact_target in {compact_id, compact_name, "foodcourta"} and location.get("name") == "Food Court A":
                        return location
                    if compact_target in {compact_id, compact_name}:
                        return location
                return None

            def ride_by_id(state: dict[str, Any], ride_id: str) -> dict[str, Any] | None:
                rides = state.get("guestFlow", {}).get("rides", [])
                return next((ride for ride in rides if ride.get("id") == ride_id), None)

            def queue_by_id(state: dict[str, Any], queue_id: str) -> dict[str, Any] | None:
                queues = state.get("physicalMap", {}).get("queues", [])
                return next((queue for queue in queues if queue.get("id") == queue_id), None)

            def guest_group_by_id(state: dict[str, Any], group_id: str) -> dict[str, Any] | None:
                groups = state.get("physicalMap", {}).get("guestGroups", [])
                return next((group for group in groups if group.get("id") == group_id), None)

            def busiest_path(state: dict[str, Any]) -> dict[str, Any]:
                paths = state.get("guestFlow", {}).get("paths", [])
                if not paths:
                    return {}
                return max(paths, key=lambda path: int(path.get("congestionLevel", 0) or 0))

            payloads = [item.get("payload", {}) for item in observed if isinstance(item.get("payload"), dict)]
            payload_text = " ".join(str(payload).lower() for payload in payloads)
            analysis_text = f"{payload_text} {str(reason).lower()}"
            domain_terms = {
                "food": ("food", "kitchen", "mobile_order", "mobile order", "menu", "pickup", "restaurant"),
                "ride": ("ride", "coaster", "dragon", "queue intake", "switchback", "attraction"),
                "staff": ("staff", "worker", "break", "crowd_control", "crowd control", "operations_lead", "understaffed"),
                "medical": ("medical", "first aid", "faint", "injury", "accessibility", "wheelchair", "mobility"),
                "crowd": ("panic", "evac", "evacuate", "security", "crowd crush", "fight", "calm route"),
                "energy": ("hvac", "temperature", "setpoint", "comfort", "lighting", "equipment_controller"),
            }
            domains = [name for name, terms in domain_terms.items() if any(term in analysis_text for term in terms)]
            explicit_medical = any(term in analysis_text for term in ("role': 'medical", '"role": "medical"', "medical team", "faint", "fainted", "first aid"))
            explicit_crowd = any(term in analysis_text for term in ("panic", "crowd congestion", "crowd safety", "security", "calm route", "evac"))
            explicit_staff = any(term in analysis_text for term in ("react_role_staff_shortage", "staff shortage", "understaffed", "overwhelmed"))
            explicit_food = any(term in analysis_text for term in ("react_role_food_spike", "food court", "mobile order", "menu_control"))
            if explicit_medical:
                primary_domain = "medical"
            elif explicit_crowd or "crowd" in domains:
                primary_domain = "crowd"
            elif explicit_staff:
                primary_domain = "staff"
            elif explicit_food:
                primary_domain = "food"
            elif "food" in domains:
                primary_domain = "food"
            elif "ride" in domains:
                primary_domain = "ride"
            elif "staff" in domains:
                primary_domain = "staff"
            elif "energy" in domains:
                primary_domain = "energy"
            else:
                primary_domain = "operations"
            food_action = primary_domain == "food"
            guest_followers = moved_guests or sum(int(item.get("response", {}).get("acceptedCount", 0) or 0) for item in observed if item.get("channel") == "guest_app")
            guest_followers = max(guest_followers, 0)
            if not moved_guests and guest_followers:
                moved_guests = guest_followers

            before_food_zone = zone_by_id(before, "foodCourt1") or {}
            before_food = food_location(before, "foodCourtA") or {}
            before_queue = queue_by_id(before, "foodPickupQueue") or {}
            before_ride = ride_by_id(before, "dragonCoaster") or {}
            before_ride_queue = queue_by_id(before, "dragonQueue") or {}
            before_coaster_zone = zone_by_id(before, "coasterPlaza") or {}
            before_staff = before.get("staffing", {}) if isinstance(before.get("staffing"), dict) else {}
            before_care = before.get("guestCare", {}) if isinstance(before.get("guestCare"), dict) else {}
            before_readiness = before.get("incidentReadiness", {}) if isinstance(before.get("incidentReadiness"), dict) else {}
            before_energy = before.get("energy", {}) if isinstance(before.get("energy"), dict) else {}
            before_path = busiest_path(before)
            before_snapshot = {
                "domain": primary_domain,
                "food_backlog": int(before_food.get("mobileOrderBacklog", 0) or 0),
                "food_eta": int(before_food.get("pickupEtaMinutes", 0) or 0),
                "food_density": int(before_food_zone.get("density", 0) or 0),
                "food_wait": int(before_food_zone.get("waitMins", 0) or 0),
                "queue_guests": int(before_queue.get("guests", 0) or 0),
                "ride_wait": int(before_ride.get("waitMins", 0) or before_ride_queue.get("waitMins", 0) or 0),
                "ride_queue": int(before_ride.get("queueGuests", 0) or before_ride_queue.get("guests", 0) or 0),
                "ride_density": int(before_coaster_zone.get("density", 0) or 0),
                "staff_callouts": int(before_staff.get("openCallouts", 0) or 0),
                "checked_in": int(before_staff.get("checkedIn", 0) or 0),
                "guest_cases": int(before_care.get("openCases", 0) or 0),
                "complaint_rate": int(before_care.get("complaintRatePct", 0) or 0),
                "path_congestion": int(before_path.get("congestionLevel", 0) or 0),
                "energy_load": int(before_energy.get("gridLoadPercent", 0) or 0),
                "emergency_access_blocked": int(bool(before_readiness.get("emergencyAccessBlocked", False))),
            }

            if food_action:
                self.scenario_key = "food_spike"
                shifted = max(40, min(260, guest_followers or 140))
                backlog_relief = max(18, min(before_snapshot["food_backlog"], round(shifted * 0.35)))
                food_zone = zone_by_id(projected, "foodCourt1")
                if food_zone:
                    food_zone["currentGuests"] = max(120, int(food_zone.get("currentGuests", 0) or 0) - shifted)
                    food_zone["density"] = _clamp(int(food_zone.get("density", 0) or 0) - max(8, round(shifted / 24)), 0, 118)
                    food_zone["waitMins"] = max(4, int(food_zone.get("waitMins", 0) or 0) - max(7, round(shifted / 35)))
                    food_zone["comfortScore"] = _clamp(int(food_zone.get("comfortScore", 0) or 0) + 9, 25, 96)
                    food_zone["dominantIntent"] = "rerouted mobile pickup"
                for relief_zone_id, guest_gain in (("arcadeZone", round(shifted * 0.18)), ("coveredPlaza", round(shifted * 0.12))):
                    relief_zone = zone_by_id(projected, relief_zone_id)
                    if relief_zone:
                        relief_zone["currentGuests"] = int(relief_zone.get("currentGuests", 0) or 0) + guest_gain
                        relief_zone["density"] = _clamp(int(relief_zone.get("density", 0) or 0) + max(1, round(guest_gain / 70)), 0, 118)
                food = food_location(projected, "foodCourtA")
                if food:
                    food["mobileOrderBacklog"] = max(0, int(food.get("mobileOrderBacklog", 0) or 0) - backlog_relief)
                    food["pickupEtaMinutes"] = max(6, int(food.get("pickupEtaMinutes", 0) or 0) - max(6, round(backlog_relief / 6)))
                    food["status"] = "intake_paused"
                    food["reroutedOrders"] = shifted
                inventory = projected.setdefault("foodInventory", {})
                suppressed = inventory.setdefault("suppressedItems", [])
                for item in ("mobile_order_intake", "chicken_tenders", "bottled_drinks"):
                    if item not in suppressed:
                        suppressed.append(item)
                food_queue = queue_by_id(projected, "foodPickupQueue")
                if food_queue:
                    food_queue["guests"] = max(0, int(food_queue.get("guests", 0) or 0) - shifted)
                    food_queue["waitMins"] = max(5, int(food_queue.get("waitMins", 0) or 0) - max(6, round(shifted / 32)))
                    food_queue["status"] = "controlled"
                    food_queue["spillbackRisk"] = "watch"
                mobile_group = guest_group_by_id(projected, "mobileOrder")
                if mobile_group:
                    mobile_group["count"] = max(20, int(mobile_group.get("count", 0) or 0) - shifted)
                    mobile_group["destination"] = "Food Court B / Main Street Shops"
                    mobile_group["mood"] = "recovering"
                    mobile_group["pace"] = "moving"
                care = projected.get("guestCare", {})
                if isinstance(care, dict):
                    care["openCases"] = max(0, int(care.get("openCases", 0) or 0) - max(3, round(shifted / 45)))
                    care["complaintRatePct"] = max(2, int(care.get("complaintRatePct", 0) or 0) - 5)
                    projected["guestCare"] = care
            elif primary_domain == "ride":
                self.scenario_key = "ride_down"
                shifted = max(80, min(360, guest_followers or 180))
                ride = ride_by_id(projected, "dragonCoaster")
                if ride:
                    ride["queueGuests"] = max(140, int(ride.get("queueGuests", 0) or 0) - shifted)
                    ride["waitMins"] = max(18, int(ride.get("waitMins", 0) or 0) - max(10, round(shifted / 24)))
                    ride["status"] = "down"
                    ride["effectiveThroughput"] = 0
                    ride["operatingDecision"] = "queue_intake_paused_pending_maintenance"
                ride_queue = queue_by_id(projected, "dragonQueue")
                if ride_queue:
                    ride_queue["guests"] = max(80, int(ride_queue.get("guests", 0) or 0) - shifted)
                    ride_queue["waitMins"] = max(12, int(ride_queue.get("waitMins", 0) or 0) - max(8, round(shifted / 28)))
                    ride_queue["status"] = "intake_paused"
                    ride_queue["spillbackRisk"] = "controlled"
                coaster_zone = zone_by_id(projected, "coasterPlaza")
                if coaster_zone:
                    coaster_zone["currentGuests"] = max(650, int(coaster_zone.get("currentGuests", 0) or 0) - shifted)
                    coaster_zone["density"] = _clamp(int(coaster_zone.get("density", 0) or 0) - max(7, round(shifted / 42)), 0, 118)
                    coaster_zone["waitMins"] = max(10, int(coaster_zone.get("waitMins", 0) or 0) - max(7, round(shifted / 46)))
                    coaster_zone["comfortScore"] = _clamp(int(coaster_zone.get("comfortScore", 0) or 0) + 8, 25, 96)
                    coaster_zone["dominantIntent"] = "exiting down ride queue"
                for zone_id, guest_gain in (("arcadeZone", round(shifted * 0.28)), ("indoorHub", round(shifted * 0.2))):
                    relief_zone = zone_by_id(projected, zone_id)
                    if relief_zone:
                        relief_zone["currentGuests"] = int(relief_zone.get("currentGuests", 0) or 0) + guest_gain
                        relief_zone["density"] = _clamp(int(relief_zone.get("density", 0) or 0) + max(1, round(guest_gain / 100)), 0, 118)
                group = guest_group_by_id(projected, "familyExitDragon")
                if group:
                    group["count"] = max(30, int(group.get("count", 0) or 0) - round(shifted * 0.35))
                    group["destination"] = "Theater B / Arcade Zone"
                    group["mood"] = "recovering"
                    group["pace"] = "moving"
                maintenance = projected.get("maintenance", {})
                if isinstance(maintenance, dict):
                    for work_order in maintenance.get("openWorkOrders", []) if isinstance(maintenance.get("openWorkOrders"), list) else []:
                        work_order["etaMinutes"] = max(20, int(work_order.get("etaMinutes", 52) or 52) - 8)
                        work_order["status"] = "inspection_prioritized"
                    projected["maintenance"] = maintenance
            elif primary_domain == "staff":
                self.scenario_key = "staff_shortage"
                acknowledged = max(worker_acks, 2)
                staffing = projected.get("staffing", {})
                if isinstance(staffing, dict):
                    staffing["checkedIn"] = int(staffing.get("checkedIn", 0) or 0) + acknowledged
                    staffing["openCallouts"] = max(0, int(staffing.get("openCallouts", 0) or 0) - acknowledged)
                    staffing["redeployedNow"] = acknowledged
                    projected["staffing"] = staffing
                staff_group = guest_group_by_id(projected, "shortStaffedOps")
                if staff_group:
                    staff_group["count"] = max(8, int(staff_group.get("count", 0) or 0) - acknowledged)
                    staff_group["destination"] = "priority zones"
                    staff_group["mood"] = "stabilizing"
                for zone_id in ("foodCourt1", "coveredPlaza"):
                    zone = zone_by_id(projected, zone_id)
                    if zone:
                        zone["waitMins"] = max(4, int(zone.get("waitMins", 0) or 0) - 5)
                        zone["comfortScore"] = _clamp(int(zone.get("comfortScore", 0) or 0) + 5, 25, 96)
                        zone["dominantIntent"] = "staff support active"
                care = projected.get("guestCare", {})
                if isinstance(care, dict):
                    care["openCases"] = max(0, int(care.get("openCases", 0) or 0) - 4)
                    projected["guestCare"] = care
            elif primary_domain in {"medical", "crowd"}:
                shifted = max(40, min(220, guest_followers or 95))
                care = projected.get("guestCare", {})
                if isinstance(care, dict):
                    care["openCases"] = max(0, int(care.get("openCases", 0) or 0) - (2 if primary_domain == "medical" else 5))
                    care["complaintRatePct"] = max(2, int(care.get("complaintRatePct", 0) or 0) - 4)
                    care["activeCareResponse"] = "medical privacy support" if primary_domain == "medical" else "crowd calming route"
                    projected["guestCare"] = care
                readiness = projected.get("incidentReadiness", {})
                if isinstance(readiness, dict):
                    readiness["emergencyAccessBlocked"] = False
                    readiness["operatorEscalation"] = "required_human_review" if primary_domain == "medical" else "watch_after_security_dispatch"
                    readiness["activeResponse"] = "medical_team_dispatched" if primary_domain == "medical" else "security_and_crowd_control_dispatched"
                    projected["incidentReadiness"] = readiness
                for route in projected.get("physicalMap", {}).get("serviceRoutes", []) if isinstance(projected.get("physicalMap", {}), dict) else []:
                    if route.get("id") == "medicalAccess":
                        route["blocked"] = False
                        route["status"] = "kept_clear"
                if primary_domain == "crowd":
                    for path in projected.get("guestFlow", {}).get("paths", []) if isinstance(projected.get("guestFlow", {}), dict) else []:
                        path["congestionLevel"] = max(35, int(path.get("congestionLevel", 0) or 0) - 12)
                        path["status"] = "busy" if int(path.get("congestionLevel", 0) or 0) >= 70 else "open"
                target_zone = "coveredPlaza" if primary_domain == "crowd" else "foodCourt1"
                zone = zone_by_id(projected, target_zone)
                if zone:
                    zone["currentGuests"] = max(120, int(zone.get("currentGuests", 0) or 0) - shifted)
                    zone["density"] = _clamp(int(zone.get("density", 0) or 0) - max(6, round(shifted / 34)), 0, 118)
                    zone["comfortScore"] = _clamp(int(zone.get("comfortScore", 0) or 0) + 7, 25, 96)
                    zone["dominantIntent"] = "calm protected access" if primary_domain == "medical" else "crowd dispersed"
                family_group = guest_group_by_id(projected, "strollerFamilies")
                if family_group:
                    family_group["destination"] = "Family Garden / Theater B" if primary_domain == "crowd" else "First Aid access route"
                    family_group["mood"] = "supported"
                    family_group["pace"] = "moving"
            elif primary_domain == "energy":
                energy = projected.get("energy", {})
                if isinstance(energy, dict):
                    energy["gridLoadPercent"] = max(55, int(energy.get("gridLoadPercent", 0) or 0) - 9)
                    energy["demandChargeRisk"] = "managed"
                    energy["activeControls"] = ["hvac_setpoint", "noncritical_lighting_shed"]
                    projected["energy"] = energy
                for zone_id in ("indoorHub", "arcadeZone", "coveredPlaza"):
                    zone = zone_by_id(projected, zone_id)
                    if zone:
                        zone["comfortScore"] = _clamp(int(zone.get("comfortScore", 0) or 0) + 4, 25, 96)
                projected.setdefault("equipmentState", {})["hvac"] = {"indoorHubSetpointF": 72, "arcadeZoneSetpointF": 73, "status": "applied"}

            after_food_zone = zone_by_id(projected, "foodCourt1") or {}
            after_food = food_location(projected, "foodCourtA") or {}
            after_queue = queue_by_id(projected, "foodPickupQueue") or {}
            after_ride = ride_by_id(projected, "dragonCoaster") or {}
            after_ride_queue = queue_by_id(projected, "dragonQueue") or {}
            after_coaster_zone = zone_by_id(projected, "coasterPlaza") or {}
            after_staff = projected.get("staffing", {}) if isinstance(projected.get("staffing"), dict) else {}
            after_care = projected.get("guestCare", {}) if isinstance(projected.get("guestCare"), dict) else {}
            after_readiness = projected.get("incidentReadiness", {}) if isinstance(projected.get("incidentReadiness"), dict) else {}
            after_energy = projected.get("energy", {}) if isinstance(projected.get("energy"), dict) else {}
            after_path = busiest_path(projected)
            after_snapshot = {
                "domain": primary_domain,
                "food_backlog": int(after_food.get("mobileOrderBacklog", 0) or 0),
                "food_eta": int(after_food.get("pickupEtaMinutes", 0) or 0),
                "food_density": int(after_food_zone.get("density", 0) or 0),
                "food_wait": int(after_food_zone.get("waitMins", 0) or 0),
                "queue_guests": int(after_queue.get("guests", 0) or 0),
                "ride_wait": int(after_ride.get("waitMins", 0) or after_ride_queue.get("waitMins", 0) or 0),
                "ride_queue": int(after_ride.get("queueGuests", 0) or after_ride_queue.get("guests", 0) or 0),
                "ride_density": int(after_coaster_zone.get("density", 0) or 0),
                "staff_callouts": int(after_staff.get("openCallouts", 0) or 0),
                "checked_in": int(after_staff.get("checkedIn", 0) or 0),
                "guest_cases": int(after_care.get("openCases", 0) or 0),
                "complaint_rate": int(after_care.get("complaintRatePct", 0) or 0),
                "path_congestion": int(after_path.get("congestionLevel", 0) or 0),
                "energy_load": int(after_energy.get("gridLoadPercent", 0) or 0),
                "emergency_access_blocked": int(bool(after_readiness.get("emergencyAccessBlocked", False))),
            }
            before_after_line_by_domain = {
                "food": f"Backlog {before_snapshot['food_backlog']} -> {after_snapshot['food_backlog']} / ETA {before_snapshot['food_eta']}m -> {after_snapshot['food_eta']}m",
                "ride": f"Ride queue {before_snapshot['ride_queue']} -> {after_snapshot['ride_queue']} / Wait {before_snapshot['ride_wait']}m -> {after_snapshot['ride_wait']}m",
                "staff": f"Callouts {before_snapshot['staff_callouts']} -> {after_snapshot['staff_callouts']} / Checked in {before_snapshot['checked_in']} -> {after_snapshot['checked_in']}",
                "medical": f"Care cases {before_snapshot['guest_cases']} -> {after_snapshot['guest_cases']} / Access blocked {before_snapshot['emergency_access_blocked']} -> {after_snapshot['emergency_access_blocked']}",
                "crowd": f"Path congestion {before_snapshot['path_congestion']} -> {after_snapshot['path_congestion']} / Cases {before_snapshot['guest_cases']} -> {after_snapshot['guest_cases']}",
                "energy": f"Grid load {before_snapshot['energy_load']}% -> {after_snapshot['energy_load']}% / Comfort +{max(0, int(after_food_zone.get('comfortScore', 0) or 0) - int(before_food_zone.get('comfortScore', 0) or 0))}",
            }
            headline_by_domain = {
                "food": f"Food Court A backlog {before_snapshot['food_backlog']} -> {after_snapshot['food_backlog']}; pickup ETA {before_snapshot['food_eta']}m -> {after_snapshot['food_eta']}m.",
                "ride": f"Dragon Coaster queue {before_snapshot['ride_queue']} -> {after_snapshot['ride_queue']}; wait {before_snapshot['ride_wait']}m -> {after_snapshot['ride_wait']}m.",
                "staff": f"Staff pressure eased: callouts {before_snapshot['staff_callouts']} -> {after_snapshot['staff_callouts']} with {worker_acks or 2} acknowledgments.",
                "medical": f"Care response active: open cases {before_snapshot['guest_cases']} -> {after_snapshot['guest_cases']} and access lane kept clear.",
                "crowd": f"Crowd response active: congestion {before_snapshot['path_congestion']} -> {after_snapshot['path_congestion']} with calmer routing.",
                "energy": f"Facilities control applied: grid load {before_snapshot['energy_load']}% -> {after_snapshot['energy_load']}%.",
            }
            state_impact = {
                "domain": primary_domain,
                "headline": headline_by_domain.get(primary_domain, f"Closed-loop receiver response changed park state across {', '.join(channels) or 'receivers'}."),
                "before_after_line": before_after_line_by_domain.get(primary_domain, f"Cases {before_snapshot['guest_cases']} -> {after_snapshot['guest_cases']}"),
                "density_delta": after_snapshot["food_density"] - before_snapshot["food_density"],
                "congestion_delta": (
                    after_snapshot["ride_wait"] - before_snapshot["ride_wait"]
                    if primary_domain == "ride"
                    else after_snapshot["path_congestion"] - before_snapshot["path_congestion"]
                    if primary_domain in {"medical", "crowd"}
                    else after_snapshot["food_wait"] - before_snapshot["food_wait"]
                ),
                "comfort_delta": int(after_food_zone.get("comfortScore", 0) or 0) - int(before_food_zone.get("comfortScore", 0) or 0),
                "queued_guest_delta": (
                    after_snapshot["ride_queue"] - before_snapshot["ride_queue"]
                    if primary_domain == "ride"
                    else after_snapshot["queue_guests"] - before_snapshot["queue_guests"]
                ),
                "before": before_snapshot,
                "after": after_snapshot,
            }
            projected["closedLoopMutation"] = {
                "reason": reason,
                "channels": channels,
                "stateImpact": state_impact,
                "appliedAt": created_at,
            }
            fitness_episode = self._record_episode_fitness_locked(
                before=before,
                after=projected,
                action_plan={"target": "traffic", "action": "reroute", "label": reason},
                source="closed_loop_dispatch_outcome",
                created_at=created_at,
                horizon_minutes=10,
                observed_response={
                    "channels": channels,
                    "movedGuests": moved_guests,
                    "workerAcknowledgments": worker_acks,
                    "equipmentCommandsApplied": equipment_applied,
                },
            )
            message = (
                f"Closed-loop outcome applied: {moved_guests} guests followed proactive routing, "
                f"{worker_acks} staff acknowledgments, {equipment_applied} equipment commands active."
            )
            self.last_actions.insert(
                0,
                {
                    "target": "outcome_loop",
                    "action": reason,
                    "message": message,
                    "channels": channels,
                    "createdAt": created_at,
                },
            )
            self.last_actions = self.last_actions[:8]
            result = {
                "status": "success",
                "message": message,
                "movedGuests": moved_guests,
                "workerAcknowledgments": worker_acks,
                "equipmentCommandsApplied": equipment_applied,
                "stateImpact": state_impact,
                "before": before_snapshot,
                "after": after_snapshot,
                "episode_fitness": fitness_episode,
            }
            self._record_replay_event(
                "outcome_applied",
                "Closed-loop dispatch outcome applied",
                before,
                self._state(include_industrial=False),
                {
                    "reason": reason,
                    "channels": channels,
                    "dispatch_count": len(dispatches),
                    "movedGuests": moved_guests,
                    "workerAcknowledgments": worker_acks,
                    "equipmentCommandsApplied": equipment_applied,
                    "status": result["status"],
                },
                created_at,
            )
            return result

    async def inject_event(self, kind: str, target_id: str, intensity: int = 75) -> dict[str, Any]:
        async with self.lock:
            before = self._state(include_industrial=False)
            intensity = max(10, min(100, int(intensity or 75)))
            created_at = _utc_now()
            event = {
                "kind": kind,
                "targetId": target_id,
                "intensity": intensity,
                "createdAt": created_at,
            }
            scenario_for_kind = {
                "ride_failure": "ride_down",
                "demand_spike": "ride_down",
                "food_spike": "food_spike",
                "staff_callout": "staff_shortage",
                "energy_spike": "storm_response",
                "storm_risk": "storm_response",
            }
            if kind in scenario_for_kind:
                self.scenario_key = scenario_for_kind[kind]
            self.active_policy = "normal"
            self.interventions.insert(0, event)
            self.interventions = self.interventions[:6]
            self.dynamic_state = apply_stress_event(before, event)
            self.last_actions.insert(
                0,
                {
                    "target": "simulation",
                    "action": kind,
                    "message": _intervention_message(kind, target_id, intensity),
                    "createdAt": event["createdAt"],
                },
            )
            self.last_actions = self.last_actions[:8]
            result = {"status": "success", "message": _intervention_message(kind, target_id, intensity), "event": deepcopy(event)}
            self._record_replay_event(
                "injected_event",
                str(kind).replace("_", " "),
                before,
                self._state(include_industrial=False),
                {"kind": kind, "targetId": target_id, "intensity": intensity, "status": result["status"]},
                created_at,
            )
            return result

    async def inject_synthetic_incident(self, plan: dict[str, Any]) -> dict[str, Any]:
        async with self.lock:
            before = self._state(include_industrial=False)
            kind = str(plan.get("kind") or "demand_spike")
            target_id = str(plan.get("target_id") or plan.get("targetId") or "coasterPlaza")
