            created_at = _utc_now()
            event = {
                "kind": kind,
                "targetId": target_id,
                "intensity": intensity,
                "createdAt": created_at,
                "synthetic": True,
                "syntheticExampleId": plan.get("synthetic_example_id"),
                "domain": plan.get("domain"),
                "expectedOwner": plan.get("expected_owner"),
                "expectedCaseId": plan.get("expected_case_id"),
                "expectedAction": plan.get("expected_action"),
                "hardConstraints": plan.get("hard_constraints", []),
                "evaluationAssertions": plan.get("evaluation_assertions", []),
                "utterance": plan.get("utterance"),
            }
            scenario_for_kind = {
                "ride_failure": "ride_down",
                "demand_spike": "ride_down",
                "food_spike": "food_spike",
                "staff_callout": "staff_shortage",
                "energy_spike": "storm_response",
                "storm_risk": "storm_response",
                "lost_child": "ride_down",
                "medical_response": "ride_down",
                "unattended_bag": "ride_down",
            }
            if kind in scenario_for_kind:
                self.scenario_key = scenario_for_kind[kind]
            self.active_policy = "normal"
            self.interventions.insert(0, event)
            self.interventions = self.interventions[:6]
            stress_kind = {
                "lost_child": "demand_spike",
                "medical_response": "demand_spike",
                "unattended_bag": "demand_spike",
            }.get(kind, kind)
            self.dynamic_state = apply_stress_event(before, {**event, "kind": stress_kind})
            self.dynamic_state = _apply_synthetic_incident_overlays(self.dynamic_state, self.interventions)
            message = _intervention_message(kind, target_id, intensity)
            self.last_actions.insert(
                0,
                {
                    "target": "synthetic",
                    "action": kind,
                    "message": message,
                    "createdAt": created_at,
                    "syntheticExampleId": plan.get("synthetic_example_id"),
                    "expectedCaseId": plan.get("expected_case_id"),
                },
            )
            self.last_actions = self.last_actions[:8]
